package com.mindbridge.safety.review;  import static org.assertj.core.api.Assertions.assertThat; import static org.assertj.core.api.Assertions.assertThatThrownBy;  import com.mindbridge.common.audit.AuditCategory; import com.mindbridge.common.domain.entity.AuditLog; import com.mindbridge.common.repository.AuditLogRepository; import com.mindbridge.safety.event.SafetyEventStatus; import com.mindbridge.safety.event.domain.SafetyEvent; import com.mindbridge.safety.event.exception.SafetyEventInputException; import com.mindbridge.safety.event.repository.SafetyEventRepository; import com.mindbridge.safety.review.dto.ExpertReviewResponse; import com.mindbridge.safety.review.dto.SafetyEventDetailResponse; import com.mindbridge.safety.review.dto.SafetyEventSummaryResponse; import com.mindbridge.safety.review.dto.SubmitReviewRequest; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.UUID; import javax.sql.DataSource; import org.junit.jupiter.api.DisplayName; import org.junit.jupiter.api.Nested; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.data.domain.Page; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Pageable; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.context.TestPropertySource; import org.springframework.test.context.jdbc.Sql;  /**  * Integration test for {@link ExpertReviewService} against the H2  * schema mirror ({@code schema-expert-reviews.sql}). Exercises the  * full persistence path: list filters pushed to JPA, detail with  * audit hook, review submission with status transition, and the  * unique-constraint duplicate-rejection path.  *  * <p>SafetyEventSource is intentionally inserted via JdbcTemplate  * (it is a POJO, not a JPA entity, in the G2 untracked baseline).  */ @SpringBootTest @ActiveProfiles("test") @TestPropertySource(properties = {         "mindbridge.ai.provider=mock",         "mindbridge.ai.mock.force-scenario=" }) @Sql(scripts = {         "/schema-safety-events.sql",         "/schema-expert-reviews.sql",         "/schema-audit.sql" }) @DisplayName("ExpertReviewService integration") class ExpertReviewServiceIntegrationTest {      @Autowired     private ExpertReviewService service;      @Autowired     private SafetyEventRepository eventRepository;      @Autowired     private ExpertReviewRepository reviewRepository;      @Autowired     private AuditLogRepository auditLogRepository;      @Autowired     private DataSource dataSource;      private JdbcTemplate jdbc() {         return new JdbcTemplate(dataSource);     }      private SafetyEvent persistEvent(UUID userId, short level, SafetyEventStatus status) {         SafetyEvent event = SafetyEvent.openFor(                 UUID.randomUUID(), userId,                 stubRow(level), "L" + level + " stub");         if (status != SafetyEventStatus.OPEN) {             if (status == SafetyEventStatus.UNDER_REVIEW) {                 event.markUnderReview();             } else if (status == SafetyEventStatus.RESOLVED) {                 event.markResolved();             } else {                 event.markDismissed();             }         }         return eventRepository.save(event);     }      private void insertSourceRow(UUID eventId, UUID sourceId) {         jdbc().update(                 "INSERT INTO safety_event_sources "                         + "(id, safety_event_id, source_type, source_id, created_at) "                         + "VALUES (?, ?, 'CHAT_ANALYSIS', ?, CURRENT_TIMESTAMP)",                 UUID.randomUUID(), eventId, sourceId);     }      private static com.mindbridge.safety.resolver.RiskStateHistory stubRow(short level) {         return com.mindbridge.safety.resolver.RiskStateHistory.record(                 UUID.randomUUID(), UUID.randomUUID(), level, level, (short) 1,                 null,                 com.mindbridge.safety.resolver.RiskStateSourceType.LLM_CLASSIFIER,                 null, "NONE", null, null,                 BigDecimal.valueOf(0.9),                 new String[]{"MAX_WINS_L" + level},                 OffsetDateTime.now());     }      @Nested     @DisplayName("listEvents filter push-down")     class ListEvents {          @Test         @DisplayName("no filter returns all events")         void noFilter() {             SafetyEvent a = persistEvent(UUID.randomUUID(), (short) 3, SafetyEventStatus.OPEN);             SafetyEvent b = persistEvent(UUID.randomUUID(), (short) 4, SafetyEventStatus.UNDER_REVIEW);              Page<SafetyEventSummaryResponse> page =                     service.listEvents(null, null, PageRequest.of(0, 20));              assertThat(page.getContent())                     .extracting(SafetyEventSummaryResponse::id)                     .contains(a.getId(), b.getId());         }          @Test         @DisplayName("status filter is pushed to DB (only matching rows on the page)")         void statusFilter() {             SafetyEvent open = persistEvent(UUID.randomUUID(), (short) 3, SafetyEventStatus.OPEN);             persistEvent(UUID.randomUUID(), (short) 4, SafetyEventStatus.UNDER_REVIEW);              Page<SafetyEventSummaryResponse> page =                     service.listEvents(SafetyEventStatus.OPEN, null, PageRequest.of(0, 20));              assertThat(page.getContent())                     .allMatch(s -> s.status() == SafetyEventStatus.OPEN);             assertThat(page.getContent())                     .extracting(SafetyEventSummaryResponse::id)                     .contains(open.getId());         }          @Test         @DisplayName("riskLevel filter is pushed to DB")         void riskLevelFilter() {             SafetyEvent l3 = persistEvent(UUID.randomUUID(), (short) 3, SafetyEventStatus.OPEN);             persistEvent(UUID.randomUUID(), (short) 4, SafetyEventStatus.OPEN);              Page<SafetyEventSummaryResponse> page =                     service.listEvents(null, Short.valueOf((short) 3), PageRequest.of(0, 20));              assertThat(page.getContent())                     .allMatch(s -> s.riskLevel() == (short) 3);             assertThat(page.getContent())                     .extracting(SafetyEventSummaryResponse::id)                     .contains(l3.getId());         }          @Test         @DisplayName("combined status + riskLevel filter")         void statusAndRiskLevelFilter() {             SafetyEvent match = persistEvent(UUID.randomUUID(), (short) 4, SafetyEventStatus.OPEN);             persistEvent(UUID.randomUUID(), (short) 4, SafetyEventStatus.UNDER_REVIEW);             persistEvent(UUID.randomUUID(), (short) 3, SafetyEventStatus.OPEN);              Page<SafetyEventSummaryResponse> page = service.listEvents(                     SafetyEventStatus.OPEN, Short.valueOf((short) 4), PageRequest.of(0, 20));              assertThat(page.getContent())                     .allMatch(s -> s.status() == SafetyEventStatus.OPEN                             && s.riskLevel() == (short) 4);             assertThat(page.getContent())                     .extracting(SafetyEventSummaryResponse::id)                     .contains(match.getId());         }          @Test         @DisplayName("reviewCount reflects existing reviews on each event")         void reviewCountEnrichment() {             SafetyEvent event = persistEvent(UUID.randomUUID(), (short) 3, SafetyEventStatus.OPEN);             ExpertReview.create(UUID.randomUUID(), event.getId(),                     UUID.randomUUID(), ExpertReviewDecision.CONTINUE_MONITORING, null);             reviewRepository.flush();              Page<SafetyEventSummaryResponse> page =                     service.listEvents(null, null, PageRequest.of(0, 20));             SafetyEventSummaryResponse summary = page.getContent().stream()                     .filter(s -> s.id().equals(event.getId()))                     .findFirst().orElseThrow();             assertThat(summary.reviewCount()).isEqualTo(1);         }     }      @Nested     @DisplayName("getEventDetailAndRecordOpened")     class Detail {          @Test         @DisplayName("returns full event with sources and reviews")         void returnsFullDetail() {             UUID userId = UUID.randomUUID();             SafetyEvent event = persistEvent(userId, (short) 4, SafetyEventStatus.OPEN);             insertSourceRow(event.getId(), UUID.randomUUID());              SafetyEventDetailResponse detail = service.getEventDetailAndRecordOpened(event.getId());              assertThat(detail.id()).isEqualTo(event.getId());             assertThat(detail.sources()).hasSize(1);             assertThat(detail.reviews()).isEmpty();         }          @Test         @DisplayName("records EXPERT_REVIEW_OPENED audit row")         void recordsAudit() {             SafetyEvent event = persistEvent(UUID.randomUUID(), (short) 3, SafetyEventStatus.OPEN);              service.getEventDetailAndRecordOpened(event.getId());              assertThat(auditLogRepository.findAll())                     .anyMatch(a -> a.getCategory() == AuditCategory.SAFETY                             && "EXPERT_REVIEW_OPENED".equals(a.getAction())                             && event.getId().equals(a.getSubjectId()));         }          @Test         @DisplayName("missing eventId throws SafetyEventInputException")         void missingEventThrows() {             UUID missing = UUID.randomUUID();             assertThatThrownBy(() -> service.getEventDetailAndRecordOpened(missing))                     .isInstanceOf(SafetyEventInputException.class)                     .hasMessageContaining("not found");         }     }      @Nested     @DisplayName("submitReview")     class Submit {          @Test         @DisplayName("happy path creates review + transitions OPEN -> UNDER_REVIEW + audit")         void happyPath() {             SafetyEvent event = persistEvent(UUID.randomUUID(), (short) 3, SafetyEventStatus.OPEN);             UUID reviewerId = UUID.randomUUID();             SubmitReviewRequest req = new SubmitReviewRequest(                     ExpertReviewDecision.ESCALATE, "needs followup");              ExpertReviewResponse response = service.submitReview(event.getId(), reviewerId, req);              assertThat(response.id()).isNotNull();             assertThat(response.decision()).isEqualTo(ExpertReviewDecision.ESCALATE);             assertThat(response.note()).isEqualTo("needs followup");             assertThat(reviewRepository.existsBySafetyEventIdAndReviewerId(event.getId(), reviewerId))                     .isTrue();             SafetyEvent refreshed = eventRepository.findById(event.getId()).orElseThrow();             assertThat(refreshed.getStatus()).isEqualTo(SafetyEventStatus.UNDER_REVIEW);             assertThat(auditLogRepository.findAll())                     .anyMatch(a -> "EXPERT_REVIEW_DECIDED".equals(a.getAction())                             && a.getActorId() != null                             && reviewerId.equals(a.getActorId())                             && event.getId().equals(a.getSubjectId()));         }          @Test         @DisplayName("does NOT re-transition an already UNDER_REVIEW event")         void idempotentTransition() {             SafetyEvent event = persistEvent(UUID.randomUUID(), (short) 3,                     SafetyEventStatus.UNDER_REVIEW);              service.submitReview(event.getId(), UUID.randomUUID(),                     new SubmitReviewRequest(ExpertReviewDecision.NO_ACTION, null));              SafetyEvent refreshed = eventRepository.findById(event.getId()).orElseThrow();             assertThat(refreshed.getStatus()).isEqualTo(SafetyEventStatus.UNDER_REVIEW);         }          @Test         @DisplayName("DISMISS decision without note is rejected")         void dismissRequiresNote() {             SafetyEvent event = persistEvent(UUID.randomUUID(), (short) 3, SafetyEventStatus.OPEN);              assertThatThrownBy(() -> service.submitReview(event.getId(), UUID.randomUUID(),                     new SubmitReviewRequest(ExpertReviewDecision.DISMISS, null)))                     .isInstanceOf(SafetyEventInputException.class)                     .hasMessageContaining("Note is required");         }          @Test         @DisplayName("DISMISS with blank note is also rejected")         void dismissRejectsBlankNote() {             SafetyEvent event = persistEvent(UUID.randomUUID(), (short) 3, SafetyEventStatus.OPEN);              assertThatThrownBy(() -> service.submitReview(event.getId(), UUID.randomUUID(),                     new SubmitReviewRequest(ExpertReviewDecision.DISMISS, "   ")))                     .isInstanceOf(SafetyEventInputException.class);         }          @Test         @DisplayName("duplicate review by same reviewer is rejected")         void duplicateRejected() {             SafetyEvent event = persistEvent(UUID.randomUUID(), (short) 3, SafetyEventStatus.OPEN);             UUID reviewerId = UUID.randomUUID();             service.submitReview(event.getId(), reviewerId,                     new SubmitReviewRequest(ExpertReviewDecision.NO_ACTION, null));              assertThatThrownBy(() -> service.submitReview(event.getId(), reviewerId,                     new SubmitReviewRequest(ExpertReviewDecision.ESCALATE, "second")))                     .isInstanceOf(DataIntegrityViolationException.class);         }          @Test         @DisplayName("closed event (RESOLVED) cannot be reviewed")         void closedEventRejected() {             SafetyEvent event = persistEvent(UUID.randomUUID(), (short) 3,                     SafetyEventStatus.RESOLVED);              assertThatThrownBy(() -> service.submitReview(event.getId(), UUID.randomUUID(),                     new SubmitReviewRequest(ExpertReviewDecision.NO_ACTION, null)))                     .isInstanceOf(SafetyEventInputException.class)                     .hasMessageContaining("closed event");         }          @Test         @DisplayName("null reviewerId rejected at the service boundary")         void nullReviewerRejected() {             SafetyEvent event = persistEvent(UUID.randomUUID(), (short) 3, SafetyEventStatus.OPEN);              assertThatThrownBy(() -> service.submitReview(event.getId(), null,                     new SubmitReviewRequest(ExpertReviewDecision.NO_ACTION, null)))                     .isInstanceOf(NullPointerException.class);         }          @Test         @DisplayName("non-existent eventId throws SafetyEventInputException")         void missingEvent() {             assertThatThrownBy(() -> service.submitReview(UUID.randomUUID(), UUID.randomUUID(),                     new SubmitReviewRequest(ExpertReviewDecision.NO_ACTION, null)))                     .isInstanceOf(SafetyEventInputException.class);         }     }      @Nested     @DisplayName("paging")     class Paging {          @Test         @DisplayName("paging + status filter does not leak off-filter rows")         void noLeakage() {             for (int i = 0; i < 5; i++) {                 persistEvent(UUID.randomUUID(), (short) 3, SafetyEventStatus.OPEN);             }             persistEvent(UUID.randomUUID(), (short) 3, SafetyEventStatus.UNDER_REVIEW);              Pageable page0 = PageRequest.of(0, 3);             Page<SafetyEventSummaryResponse> p =                     service.listEvents(SafetyEventStatus.OPEN, null, page0);              assertThat(p.getContent()).hasSize(3);             assertThat(p.getContent())                     .allMatch(s -> s.status() == SafetyEventStatus.OPEN);         }     } }